const originalText=new WeakMap(),originalAttrs=new WeakMap();
const safeNodes='input,textarea,pre,script,style,[data-private],#client-list';
function translatedText(text,lang){
 const leading=text.match(/^\s*/)[0],trailing=text.match(/\s*$/)[0],v=text.trim(); if(!v)return text;
 if(lang==='en'){
  let out=(ENGLISH_SHEET[v]&&!(v.length<5&&!['நா.','வி.'].includes(v)))?ENGLISH_SHEET[v]:v;
  for(const [en,ta] of Object.entries(SIGNS_I18N))out=out.replaceAll(`${en} (${ta})`,en).replaceAll(`${en} · ${ta}`,en).replaceAll(ta,en);
  for(const [en,ta] of Object.entries(PLANETS_I18N))out=out.replaceAll(`${ta} / ${en}`,en);
  for(const [ta,en] of Object.entries(ENGLISH_SHEET).filter(([x])=>x.length>4||['நா.','வி.'].includes(x)).sort((a,b)=>b[0].length-a[0].length))out=out.replaceAll(ta,en);
  for(const [ta,en] of Object.entries(TAMIL_NAMES_EN).sort((a,b)=>b[0].length-a[0].length))out=out.replaceAll(ta,en);
  return leading+out+trailing;
 }
 if(UI_TRANSLATIONS[v])return leading+UI_TRANSLATIONS[v]+trailing;
 let out=translateFragments(v,true);out=tamilTemplates(out);out=translateFragments(out);
 for(const [en,ta] of Object.entries(SIGNS_I18N))out=out.replaceAll(`${en} (${ta})`,ta).replaceAll(`${en} · ${ta}`,ta).replace(new RegExp(`\\b${en}\\b`,'g'),ta);
 for(const [en,ta] of Object.entries(PLANETS_I18N))out=out.replaceAll(`${ta} / ${en}`,ta).replace(new RegExp(`\\b${en}\\b`,'g'),ta);
 out=out.replace(/\bto\b/gi,'முதல்').replace(/\babout\b/gi,'சுமார்').replace(/\blagna\b/gi,'லக்னம்').replace(/\bperiod\b/g,'காலம்').replace(/\band\b/g,'மற்றும்');
 out=out.replace(/\b(mean|true)\b/g,x=>x==='mean'?'சராசரி':'உண்மை').replace(/(\d+(?:\.\d+)?)-day year/g,'$1 நாள் ஆண்டு').replace(/\bStands out for:/g,'முக்கிய துறைகள்:').replace(/\bRuling planet for this stretch:/g,'இந்தக் காலத்தின் அதிபதி:').replace(/\bRuling planet:/g,'அதிபதி:').replace(/\bSupports:/g,'ஆதரவு:').replace(/\bNeeds care:/g,'கவனம் தேவை:').replace(/\bRight now/g,'இப்போது').replace(/\bNext/g,'அடுத்து').replace(/\bNow/g,'இப்போது').replace(/\btesting\b/g,'சவாலானது').replace(/\bsupportive\b/g,'ஆதரவானது').replace(/\bmixed\b/g,'கலந்தது').replace(/\bPDF page\b/g,'PDF பக்கம்').replace(/\bchapter\b/g,'அத்தியாயம்').replace(/\bverse\b/g,'சுலோகம்');
 out=out.replace(/(\d+)(?:st|nd|rd|th)/g,'$1-ம்');for(const [en,ta] of Object.entries(ZONE_NAMES))out=out.replaceAll(en,ta);
 return leading+out+trailing;
}
function localizeInterface(root=document.body){
 const nodes=[];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){if(!node.parentElement||node.parentElement.closest(safeNodes)||node.parentElement.closest('#language-switch'))continue;const stored=originalText.get(node);const original=stored&&node.textContent===stored.last?stored.original:node.textContent;const next=translatedText(original,interfaceLanguage);originalText.set(node,{original,last:next});if(node.textContent!==next)node.textContent=next;}
 for(const el of root.querySelectorAll('[placeholder],[aria-label]')){if(el.closest('[data-private],#language-switch'))continue;const state=originalAttrs.get(el)||{};for(const key of ['placeholder','aria-label']){if(!el.hasAttribute(key))continue;const prev=state[key];const raw=prev&&el.getAttribute(key)===prev.last?prev.original:el.getAttribute(key);const next=translatedText(raw,interfaceLanguage);state[key]={original:raw,last:next};if(el.getAttribute(key)!==next)el.setAttribute(key,next);}originalAttrs.set(el,state);}
}
