function setupLanguages(){
 const group=document.createElement('div');group.id='language-switch';group.setAttribute('role','group');group.setAttribute('aria-label','மொழி / Language');group.innerHTML='<button type="button" data-language="ta" lang="ta">தமிழ்</button><button type="button" data-language="en" lang="en">English</button>';
 document.querySelector('header').append(group);
 const observer=new MutationObserver(()=>{observer.disconnect();localizeInterface();observer.observe(document.body,{subtree:true,childList:true,characterData:true});});
 function setLanguage(lang){interfaceLanguage=lang;document.documentElement.lang=lang;document.title=lang==='ta'?'ஜாதகம் | பிறப்பு விவரங்களும் வாசிப்பும்':'Horoscope | Birth chart and reading';try{localStorage.setItem('horoscope-language',lang);}catch{}for(const b of group.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.language===lang));
  observer.disconnect();if(typeof syncDate==='function')syncDate();
  if(window.__lastReport&&window.__lastBirth){const was=window.__lastReport,birth=window.__lastBirth,wasHidden=output.hidden,emptyHidden=document.querySelector('#empty').hidden;const open=[...document.querySelectorAll('#results details[open]')].map(d=>[...document.querySelectorAll('#results details')].indexOf(d));render(was,birth,window.__lastCoords);output.hidden=wasHidden;document.querySelector('#empty').hidden=emptyHidden;document.querySelectorAll('#results details').forEach((d,i)=>{if(open.includes(i))d.open=true;});}
  document.dispatchEvent(new Event('languagechange'));localizeInterface();observer.observe(document.body,{subtree:true,childList:true,characterData:true});
 }
 group.addEventListener('click',e=>{const b=e.target.closest('[data-language]');if(b)setLanguage(b.dataset.language);});setLanguage(interfaceLanguage);
 window.addEventListener('storage',e=>{if(e.key==='horoscope-language')setLanguage(e.newValue==='en'?'en':'ta');});
 document.addEventListener('invalid',e=>{const el=e.target;if(interfaceLanguage==='ta'&&el.setCustomValidity)el.setCustomValidity(el.validity.valueMissing?'இந்த விவரத்தை நிரப்புங்கள்.':el.validity.rangeUnderflow||el.validity.rangeOverflow?'அனுமதிக்கப்பட்ட வரம்பிற்குள் மதிப்பை அளிக்கவும்.':'இந்த விவரத்தைச் சரிபார்க்கவும்.');},true);document.addEventListener('input',e=>e.target.setCustomValidity?.(''));document.addEventListener('languagechange',()=>document.querySelectorAll('input,select,textarea').forEach(e=>e.setCustomValidity('')));const nativeConfirm=window.confirm.bind(window);window.confirm=msg=>nativeConfirm(translatedText(msg,interfaceLanguage));
}
window.addEventListener('DOMContentLoaded',setupLanguages);

